# ── BoardX: live Shuffleboard / NetworkTables values ───────────────────

class BoardX:
    """NetworkTables client (pynetworktables, NT3 like WPILib 2020)."""

    def __init__(self):
        self.inst = None
        self.host = None

    def connect(self, request):
        host = str(request.get("host", "")).strip()
        if not host or any(c in host for c in "/@?# "):
            raise ValueError("Укажите адрес робота (например raspberrypi.local или 10.0.0.2)")
        try:
            from networktables import NetworkTablesInstance
        except ImportError:
            raise ValueError("BoardX: нужен pynetworktables — pip install pynetworktables")
        if self.inst is not None:
            try:
                self.inst.stopClient()
            except Exception:  # noqa: BLE001 - old client may be half-closed
                pass
        self.inst = NetworkTablesInstance.create()
        self.inst.setNetworkIdentity("MapperX")
        self.inst.startClient((host, NetworkTablesInstance.DEFAULT_PORT))
        self.inst.setUpdateRate(0.05)
        self.host = host
        return {"ok": True, "host": host}

    def poll(self, _request):
        if self.inst is None:
            return {"connected": False, "values": {}}
        values = {}
        for entry in self.inst.getEntries("", 0):
            value = entry.value
            if isinstance(value, (bytes, bytearray)):
                continue
            if isinstance(value, tuple):
                value = list(value)
            values[entry.getName()] = value
        return {"connected": bool(self.inst.isConnected()), "host": self.host, "values": values,
                "time": time.time()}

    def put(self, request):
        if self.inst is None or not self.inst.isConnected():
            raise ValueError("Нет связи с роботом")
        key, value = request.get("key"), request.get("value")
        if not isinstance(key, str) or not key.startswith("/"):
            raise ValueError("Неверный ключ")
        entry = self.inst.getEntry(key)
        old = entry.value
        if isinstance(old, bool):
            value = bool(value)
        elif isinstance(old, (int, float)):
            value = float(value)
        elif isinstance(old, str):
            value = str(value)
        else:
            raise ValueError("Этот тип менять нельзя")
        entry.setValue(value)
        return {"ok": True}

    def disconnect(self, _request):
        if self.inst is not None:
            self.inst.stopClient()
            self.inst = None
        return {"ok": True}


# ── PinX: what is wired where, read from the Java code ─────────────────

PIN_KINDS = {
    "Servo": ("pwm", "Серво (PWM)"), "PWM": ("pwm", "PWM"), "PWMSpeedController": ("pwm", "PWM-мотор"),
    "DigitalInput": ("dio", "Цифровой вход"), "DigitalOutput": ("dio", "Цифровой выход"),
    "Ultrasonic": ("dio", "Ультразвук (ping, echo)"), "Encoder": ("dio", "Энкодер DIO"),
    "Counter": ("dio", "Счётчик"),
    "AnalogInput": ("ain", "Аналоговый вход"), "AnalogPotentiometer": ("ain", "Потенциометр"),
    "TitanQuad": ("can", "Мотор TitanQuad (CAN id, канал)"),
    "TitanQuadEncoder": ("can", "Энкодер TitanQuad"),
    "AHRS": ("bus", "Гироскоп navX"), "Joystick": ("usb", "Геймпад (USB-порт ПК)"),
    "XboxController": ("usb", "Геймпад Xbox"),
}
PIN_NEW_RE = re.compile(r"^(?P<indent>[ \t]*)(?P<comment>//\s*)?(?:[\w<>]+\s+)?(?P<var>\w+)\s*=\s*new\s+"
                        r"(?P<cls>" + "|".join(PIN_KINDS) + r")\s*\((?P<args>[^;]*)\)\s*;", re.M)


def _java_constants():
    consts = {}
    for path in (PROJECT_DIR / "src" / "main" / "java").rglob("*.java"):
        for m in JAVA_CONST_RE.finditer(path.read_text(encoding="utf-8", errors="replace")):
            consts[m.group("name")] = m.group("val")
    return consts


def pinx_list(_request):
    consts = _java_constants()
    pins = []
    for path in sorted((PROJECT_DIR / "src" / "main" / "java").rglob("*.java")):
        text = path.read_text(encoding="utf-8", errors="replace")
        lines = text.split("\n")
        for m in PIN_NEW_RE.finditer(text):
            line_no = text.count("\n", 0, m.start())
            kind, title = PIN_KINDS[m.group("cls")]
            args = []
            depth, cur = 0, ""
            for ch in m.group("args"):
                if ch == "," and depth == 0:
                    args.append(cur.strip())
                    cur = ""
                    continue
                depth += ch == "("
                depth -= ch == ")"
                cur += ch
            if cur.strip():
                args.append(cur.strip())
            resolved = []
            for a in args:
                key = a.split(".")[-1]
                resolved.append({"src": a, "value": consts.get(key, a if re.match(r"^-?\d+$", a) else None),
                                 "const": key if key in consts else None})
            pins.append({"file": path.relative_to(PROJECT_DIR).as_posix(), "line": line_no + 1,
                         "var": m.group("var"), "cls": m.group("cls"), "kind": kind, "title": title,
                         "args": resolved, "disabled": bool(m.group("comment")),
                         "note": _comment_above(lines, line_no)})
    return {"pins": pins}


def pinx_set(request):
    """Changes a literal channel number in one `new X(...)` line."""
    rel, line, index, value = request.get("file"), request.get("line"), request.get("arg"), request.get("value")
    if not isinstance(rel, str) or type(line) is not int or type(index) is not int:
        raise ValueError("Неверный пин")
    if not re.match(r"^\d{1,3}$", str(value)):
        raise ValueError("Канал — целое число")
    path = (PROJECT_DIR / rel).resolve()
    if path.suffix != ".java" or (PROJECT_DIR / "src").resolve() not in path.parents:
        raise ValueError("Файл не из проекта")
    lines = path.read_text(encoding="utf-8").split("\n")
    m = PIN_NEW_RE.match(lines[line - 1])
    if not m:
        raise ValueError("Строка изменилась — обновите список")
    args = [a.strip() for a in m.group("args").split(",")]
    if not 0 <= index < len(args) or not re.match(r"^\d+$", args[index]):
        raise ValueError("Этот аргумент — константа, меняйте её в TuneX")
    args[index] = str(value)
    s = lines[line - 1]
    lines[line - 1] = s[:m.start("args")] + ", ".join(args) + s[m.end("args"):]
    write_text(path, "\n".join(lines))
    return {"ok": True}


